// Type for translation keys
export type TranslationKey = keyof typeof translations.en;

// Simple translation function with interpolation support
export function t(key: TranslationKey, languageOrParams?: Language | Record<string, string | number>, maybeLanguage?: Language): string {
  let language: Language = 'vi';
  let params: Record<string, string | number> | undefined;
  
  if (typeof languageOrParams === 'object' && languageOrParams !== null) {
    params = languageOrParams;
    language = maybeLanguage || 'vi';
  } else if (typeof languageOrParams === 'string') {
    language = languageOrParams;
  }
  
  const lang = translations[language] as Record<string, string>;
  const vi = translations.vi as Record<string, string>;
  let text = lang?.[key] || vi[key] || key;
  
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
  }
  
  return text;
}

// React hook for translations
export function useTranslation() {
  const language = useLanguageStore((state) => state.language ?? 'vi') as Language;
  
  // Force re-render when language changes - important for zustand persist
  const [, forceUpdate] = useState(0);
  useEffect(() => {
    forceUpdate(n => n + 1);
  }, [language]);
  
  // Memoize the t function so it only changes when language changes
  const tFn = useMemo(() => {
    return (key: TranslationKey, params?: Record<string, string | number>) => t(key, params, language);
  }, [language]);
  
  return {
    t: tFn,
    language,
  };
}
